var o=[{title:`Estiramiento estático`,text:`Un estiramiento estático mantiene con suavidad un músculo o una articulación cerca del final de su rango cómodo. Un estiramiento de gemelos contra una pared o un estiramiento de flexores de la cadera con apoyo, por ejemplo, pueden mantenerse un rato corto sin rebotes. Debería sentirse como una tensión suave, nunca como un dolor agudo ni un entumecimiento.`},{title:`Estiramiento dinámico`,text:`El estiramiento dinámico recorre un rango útil una y otra vez: balanceos de pierna que puedes controlar, círculos de brazos, zancadas alternas. Cada repetición es deliberada, sin rebotes ni prisas. Estos ejercicios encajan de forma natural en un calentamiento para correr, levantar pesas y practicar deportes.`},{title:`Cuándo usar cada uno`,text:`Antes de un esfuerzo explosivo, suelen funcionar mejor el movimiento dinámico gradual y la práctica del propio ejercicio. El estiramiento estático largo e intenso justo antes puede reducir brevemente la fuerza o la potencia, mientras que unas pocas retenciones cortas preocupan menos. Después del entrenamiento o en una sesión aparte, el estiramiento estático es una forma razonable de trabajar la flexibilidad.`},{title:`Cuánto hacer`,text:`Usa retenciones cortas y cómodas y repítelas a lo largo de semanas en lugar de forzar un rango nuevo en una sola sesión. En los ejercicios dinámicos, empieza con un rango pequeño y amplíalo solo mientras el movimiento siga controlado. El estiramiento no necesita doler para funcionar, y más flexibilidad no ayuda en todas las tareas.`},{title:`Lo que el estiramiento no puede prometer`,text:`Usa los ejercicios dinámicos para prepararte para el movimiento activo y las retenciones estáticas cuando el objetivo sea la flexibilidad. Ninguno te hace a prueba de lesiones ni previene de forma fiable las agujetas. Si el dolor persiste, pide a un médico o a un fisioterapeuta un consejo que se ajuste a ti.`}];var n=[{label:`ACE 2026: guía práctica sobre estiramientos`,url:`https://www.acefitness.org/continuing-education/certified/april-2026/9104/new-expert-guidance-on-stretching-what-belongs-in-your-programs/?authorScope=80`},{label:`ACE 2026: movilidad frente a flexibilidad`,url:`https://www.acefitness.org/continuing-education/certified/may-2026/9119/mobility-vs-flexibility-why-the-difference-matters-for-movement-and-performance/`},{label:`NHS: ejercicios suaves de vuelta a la calma`,url:`https://www.nhs.uk/live-well/exercise/strength-and-resistance/body-blast-cool-down/`}];var i={sections:o,sources:n};export{i as default,o as sections,n as sources};